// Chromium may round the first nearest scroll down while the CSS box ends
// at a fractional coordinate. The computed residual must still be exposed.
const fractionalRect={top:900,bottom:944,width:300,height:44},fractional=element('fractional-next-action',fractionalRect);
fractional.scrollIntoView=options=>{calls.push({type:'scroll',id:fractional.id,options});fractionalRect.top=808.375;fractionalRect.bottom=852.375;};
c.window.scrollBy=options=>{calls.push({type:'residual-scroll',id:fractional.id,options});fractionalRect.top-=options.top;fractionalRect.bottom-=options.top;};
c.ui.focus(fractional);
assert.ok(fractionalRect.bottom<=c.innerHeight,'FOCUS_FRACTIONAL_EDGE_ORACLE: nearest scrolling left the actual action clipped');
assert.ok(calls.find(call=>call.type==='residual-scroll')?.options.top>0,'Fractional correction must move forward, not upward');
cases.push({caseId:'FOCUS-FRACTIONAL-EDGE',result:'PASS',bottomAfterCorrection:fractionalRect.bottom,viewportHeight:c.innerHeight});calls.length=0;delete c.window.scrollBy;

// Synthetic writes select current project state through an ordinary project link.
// Reloading a saved-version URL intentionally restores that saved version instead.
async function openStoredFixture(cdp){const url=await evalValue(cdp,`(async()=>{const url=new URL(location.href);url.searchParams.delete('version');url.searchParams.delete('stage');url.searchParams.set('project',await closedLoopProjectStore.metaGet('selectedProject'));return url.href;})()`);await cdp.send('Page.navigate',{url});}

closedLoopWorkflowEngine.addHistory(next,'CORRECTION_REQUESTED',{stage:3,operation:'COMPLETE',rejectedResponseId:'PRESSURE-CORRECTION',rawResponseId:'PRESSURE-RAW'});await store.writeProject(next);})()`);
 await openStoredFixture(cdp);await waitExpr(cdp,`closedLoopAppReady===true`,30000);await openStage(cdp,3);
 assert(await evalValue(cdp,`closedLoopProjectStore.readProject('JOB-20260823144121').then(p=>p.projectData.rejectedResponses.some(row=>row.rejectedResponseId==='PRESSURE-CORRECTION'&&row.reason.endsWith('EXPORT-CONTEXT-TAIL')))`),'The ordinary project link did not activate the current pressure fixture.'

// Removal belongs to the application's operation owner, which captures the
  // departing view and excludes concurrent scroll checkpoints before committing.
  await click(cdp,'[data-view="Project"]',60000);
  await click(cdp,'#project-danger-zone>summary',60000);
  await fill(cdp,'#delete-project-confirmation','BROWSER-ACCUMULATED-HISTORY');
  await click(cdp,'#delete-project',60000);
  await waitFor(cdp,`closedLoopProjectStore.readProject('BROWSER-ACCUMULATED-HISTORY').then(project=>!project)`,60000);
  assert(await evaluate(cdp,`closedLoopProjectStore.historyList('BROWSER-ACCUMULATED-HISTORY').then(history=>history.removed&&history.entries.length>0)`),'Project removal lost promised History.'
